-- Sample Rich Bangla MCQs (with Board/Year, Explanations, Math & Complex Types)
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (1, 'চোখের কোন অংশ ক্যামেরার ডায়াফ্রামের মতো কাজ করে?', 'simple', NULL, NULL, '["রেটিনা", "আইরিশ", "কর্নিয়া", "অক্ষিগোলক"]', 'আইরিশ', 'আইরিশ পিউপিলের আকার পরিবর্তন করে আলো নিয়ন্ত্রণ করে, যা ক্যামেরার ডায়াফ্রামের অনুরূপ।', 'ঢা. বো.', 2020, 357, 'easy', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (2, 'সাধারণ চোখের স্পষ্ট দর্শনের নিকটতম দূরত্ব কত?', 'simple', NULL, NULL, '["15 cm", "20 cm", "25 cm", "50 cm"]', '25 cm', 'একজন স্বাভাবিক পূর্ণবয়স্ক মানুষের চোখের স্পষ্ট দর্শনের নিকটতম দূরত্ব ২৫ সেমি।', 'রা. বো.', 2023, 357, 'easy', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (3, 'লেন্সের ক্ষমতার আন্তর্জাতিক (SI) একক কোনটি?', 'simple', NULL, NULL, '["ডায়প্টার (D)", "মিটার (m)", "রেডিয়ান", "ওয়াট"]', 'ডায়প্টার (D)', 'লেন্সের ক্ষমতার প্রচলিত ও এসআই আন্তর্জাতিক একক হলো ডায়প্টার ($m^{-1}$)।', 'য. বো.', 2021, 357, 'easy', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (4, 'রেটিনার ওপর সৃষ্ট প্রতিবিম্বের প্রকৃতি কীরূপ?', 'simple', NULL, NULL, '["সোজা ও বাস্তব", "উল্টো ও বাস্তব", "সোজা ও অবাস্তব", "উল্টো ও অবাস্তব"]', 'উল্টো ও বাস্তব', 'চোখের উত্তল লেন্স রেটিনার ওপর বাস্তব এবং উল্টো প্রতিবিম্ব তৈরি করে; মস্তিষ্ক তা সোজা করে নেয়।', 'কু. বো.', 2022, 357, 'medium', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (5, 'ক্ষীণদৃষ্টি বা হ্রস্বদৃষ্টি (Myopia) দূর করার জন্য কোন লেন্সের চশমা ব্যবহৃত হয়?', 'simple', NULL, NULL, '["উত্তল লেন্স", "অবতল লেন্স", "বেলনাকার লেন্স", "বাইফোকাল লেন্স"]', 'অবতল লেন্স', 'ক্ষীণদৃষ্টিতে অভিসারী ক্ষমতা বেড়ে যায়, অপসারী অবতল লেন্সের মাধ্যমে আলো অপসারিত করে রেটিনায় ফেলা হয়।', 'চ. বো.', 2020, 357, 'medium', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (6, 'একটি লেন্সের ফোকাস দূরত্ব +০.৫ মিটার হলে এর ক্ষমতা কত?', 'simple', NULL, NULL, '["-২ D", "+০.৫ D", "+১ D", "+২ D"]', '+২ D', 'ক্ষমতা $P = \frac{1}{f} = \frac{1}{+0.5} = +2\text{ D}$ (উত্তল লেন্স)।', 'সি. বো.', 2022, 357, 'medium', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (7, 'কম আলোতে দর্শনের জন্য রেটিনার কোন কোষগুলো সংবেদনশীল?', 'simple', NULL, NULL, '["কোণ কোষ", "রড কোষ", "অন্ধবিন্দু", "পীতবিন্দু"]', 'রড কোষ', 'রড কোষ অনুজ্জ্বল ও মৃদু আলোতে দেখতে সহায়তা করে (রডোপসিন প্রোটিন সমৃদ্ধ)।', 'ব. বো.', 2019, 357, 'medium', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (8, 'অপটিক্যাল ফাইবারে আলোর কোন ঘটনাটি সংঘটিত হয়?', 'simple', NULL, NULL, '["নিয়মিত প্রতিফলন", "পূর্ণ অভ্যন্তরীণ প্রতিফলন", "অপবর্তন", "বিচ্ছুরণ"]', 'পূর্ণ অভ্যন্তরীণ প্রতিফলন', 'অপটিক্যাল ফাইবারে অভ্যন্তরীণ প্রতিফলন কাজে লাগিয়ে দ্রুত আলোক সংকেত পাঠানো হয়।', 'ঢা. বো.', 2019, 357, 'easy', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (9, 'একটি চশমার ক্ষমতা +৩.০ D হলে এর ফোকাস দূরত্ব কত?', 'simple', NULL, NULL, '["+০.৩৩ মিটার", "+৩.০ মিটার", "-০.৩৩ মিটার", "+১.৫ মিটার"]', '+০.৩৩ মিটার', '$f = \frac{1}{P} = \frac{1}{+3.0} = +0.33\text{ m}$ (৩৩.৩৩ সেমি)।', 'ব. বো.', 2021, 357, 'medium', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (10, 'পূর্ণ অভ্যন্তরীণ প্রতিফলনের জন্য প্রযোজ্য—', 'complex', '["i. আলো ঘন মাধ্যম থেকে হালকা মাধ্যমে যাবে", "ii. আপতন কোণ সংকট কোণের চেয়ে বড় হবে", "iii. প্রতিসরণ কোণ ৯০° হবে"]', 'নিচের কোনটি সঠিক?', '["i ও ii", "i ও iii", "ii ও iii", "i, ii ও iii"]', 'i ও ii', 'পূর্ণ অভ্যন্তরীণ প্রতিফলনের দুটি শর্ত: আলো ঘন থেকে হালকা মাধ্যমে যাবে এবং আপতন কোণ সংকট কোণের চেয়ে বড় হবে।', 'ঢা. বো.', 2023, 357, 'hard', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (11, 'আলোর প্রতিসরণের সময় কোনটি অপরিবর্তিত থাকে?', 'simple', NULL, NULL, '["বেগ", "তরঙ্গদৈর্ঘ্য", "কম্পাঙ্ক", "দিক"]', 'কম্পাঙ্ক', 'প্রতিসরণের সময় আলোর বেগ ও তরঙ্গদৈর্ঘ্য পরিবর্তিত হলেও উৎসের ওপর নির্ভরশীল কম্পাঙ্ক অপরিবর্তিত থাকে।', 'রা. বো.', 2019, 357, 'medium', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (12, 'কোন ভিটামিনের অভাবে চোখে রাতকানা রোগ সৃষ্টি হয়?', 'simple', NULL, NULL, '["ভিটামিন বি", "ভিটামিন সি", "ভিটামিন এ", "ভিটামিন ডি"]', 'ভিটামিন এ', 'রেটিনার রড কোষের রডোপসিন গঠনে ভিটামিন এ অপরিহার্য; এর অভাবে রাতকানা হয়।', 'য. বো.', 2019, 357, 'easy', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (13, 'যদি $x + \frac{1}{x} = 3$ হয়, তবে $x^2 + \frac{1}{x^2}$ এর মান কত?', 'simple', NULL, NULL, '["7", "9", "11", "5"]', '7', '$x^2 + \frac{1}{x^2} = (x + \frac{1}{x})^2 - 2 = 3^2 - 2 = 7$।', 'ঢা. বো.', 2023, 331, 'medium', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (14, 'যদি $a + b = 5$ এবং $ab = 4$ হয়, তবে $(a - b)^2$ এর মান কত?', 'simple', NULL, NULL, '["9", "16", "21", "41"]', '9', '$(a - b)^2 = (a + b)^2 - 4ab = 5^2 - 4(4) = 25 - 16 = 9$।', 'রা. বো.', 2022, 331, 'easy', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (15, 'বাস্তব সংখ্যার ক্ষেত্রে নিচের বিবৃতিগুলো লক্ষ কর:', 'complex', '["i. সকল মূলদ সংখ্যাই বাস্তব সংখ্যা", "ii. $\\sqrt{2}$ একটি অমূলদ সংখ্যা", "iii. শূন্য একটি ধনাত্মক সংখ্যা"]', 'নিচের কোনটি সঠিক?', '["i ও ii", "i ও iii", "ii ও iii", "i, ii ও iii"]', 'i ও ii', 'শূন্য ধনাত্মক বা ঋণাত্মক কোনোটিই নয়; তবে সকল মূলদ সংখ্যা ও $\sqrt{2}$ বাস্তব সংখ্যা।', 'চ. বো.', 2023, 331, 'hard', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (16, 'a² - b² এর উৎপাদক কোনটি?', 'simple', NULL, NULL, '["(a+b)(a-b)", "(a+b)²", "(a-b)²", "a²+2ab+b²"]', '(a+b)(a-b)', 'বীজগাণিতিক অভেদ অনুযায়ী $a^2 - b^2 = (a + b)(a - b)$।', 'সি. বো.', 2021, 331, 'easy', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (17, 'কোনো সেটের উপাদান সংখ্যা 3 হলে, এর উপসেট সংখ্যা কত?', 'simple', NULL, NULL, '["3", "6", "8", "9"]', '8', 'উপাদান সংখ্যা $n = 3$ হলে উপসেট সংখ্যা $2^n = 2^3 = 8$।', 'কু. বো.', 2023, 331, 'easy', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (18, 'ত্রিভুজের তিন কোণের সমষ্টি কত ডিগ্রি?', 'simple', NULL, NULL, '["90°", "180°", "270°", "360°"]', '180°', 'ইউক্লিডীয় জ্যামিতিতে যেকোনো ত্রিভুজের তিন কোণের সমষ্টি দুই সমকোণ বা $180^\circ$।', 'ব. বো.', 2020, 331, 'easy', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (19, '(1/x) + (1/y) এর সরলকৃত মান কোনটি?', 'simple', NULL, NULL, '["(x+y)/(xy)", "xy/(x+y)", "2/(x+y)", "1/(xy)"]', '(x+y)/(xy)', 'ভগ্নাংশের যোগফল: $\frac{1}{x} + \frac{1}{y} = \frac{x+y}{xy}$।', 'য. বো.', 2022, 331, 'medium', 1, 1);
INSERT OR IGNORE INTO questions (id, question_text, question_type, sub_options, final_prompt, answer_options, correct_answer, explanation, board, year, chapter_id, difficulty, marks, is_active) VALUES (20, 'পানি থেকে আলো বাতাসে প্রবেশের সময় সংকট কোণ প্রায় কত?', 'simple', NULL, NULL, '["24°", "42°", "49°", "90°"]', '49°', 'পানি ও বায়ুর জন্য সংকট কোণের মান $48.6^\circ$ বা প্রায় $49^\circ$।', 'দি. বো.', 2018, 357, 'medium', 1, 1);

-- Sample Short Questions (খ-বিভাগ)
INSERT OR IGNORE INTO short_questions (id, subject_id, chapter_id, question_text, answer, marks, board, year, is_active) VALUES (1, 52, 357, 'লেন্সের ক্ষমতা কাকে বলে? এর এসআই একক লেখ।', 'কোনো লেন্সের অভিসারী বা অপসারী ক্ষমতার পরিমাপকে লেন্সের ক্ষমতা বলে; এর একক ডায়প্টার (D)।', 2, 'ঢা. বো.', 2023, 1);
INSERT OR IGNORE INTO short_questions (id, subject_id, chapter_id, question_text, answer, marks, board, year, is_active) VALUES (2, 52, 357, 'ক্ষীণদৃষ্টি বা মায়োপিয়া কী এবং কীভাবে প্রতিকার করা হয়?', 'কাছের বস্তু স্পষ্ট দেখলেও দূরের বস্তু ঝাপসা দেখা যায়; অবতল লেন্সের চশমা ব্যবহারে এর প্রতিকার হয়।', 2, 'রা. বো.', 2022, 1);
INSERT OR IGNORE INTO short_questions (id, subject_id, chapter_id, question_text, answer, marks, board, year, is_active) VALUES (3, 52, 357, 'পূর্ণ অভ্যন্তরীণ প্রতিফলনের দুটি শর্ত লেখ।', '১) আলো ঘন মাধ্যম থেকে হালকা মাধ্যমে যাবে, ২) আপতন কোণ সংকট কোণের চেয়ে বড় হবে।', 2, 'চ. বো.', 2021, 1);
INSERT OR IGNORE INTO short_questions (id, subject_id, chapter_id, question_text, answer, marks, board, year, is_active) VALUES (4, 50, 331, 'যদি $x - \frac{1}{x} = 4$ হয়, তবে $x^2 + \frac{1}{x^2}$ এর মান নির্ণয় কর।', '$x^2 + \frac{1}{x^2} = (x - \frac{1}{x})^2 + 2 = 16 + 2 = 18$', 2, 'য. বো.', 2023, 1);
INSERT OR IGNORE INTO short_questions (id, subject_id, chapter_id, question_text, answer, marks, board, year, is_active) VALUES (5, 50, 331, 'অমূলদ সংখ্যা কাকে বলে? একটি উদাহরণ দাও।', 'যে সংখ্যাকে $\frac{p}{q}$ আকারে প্রকাশ করা যায় না, যেমন $\sqrt{2}$।', 2, 'সি. বো.', 2022, 1);

-- Sample Creative Questions (গ-বিভাগ সৃজনশীল)
INSERT OR IGNORE INTO cq_questions (id, subject_id, chapter_id, stem, part_ka, part_kha, part_ga, part_gha, marks_ka, marks_kha, marks_ga, marks_gha, board, year, is_active) VALUES (1, 52, 357, 'রহিম সাহেব দূরের সাইনবোর্ড স্পষ্ট দেখতে পান না, কিন্তু কাছের বই পড়তে পারেন। অপরদিকে তার পিতা +2.5 D ক্ষমতার চশমা ব্যবহার করেন।', 'চোখের উপযোজন কী?', 'রহিম সাহেবের চোখের ত্রুটিটির নাম কী এবং এর কারণ ব্যাখ্যা কর।', 'রহিম সাহেবের পিতার চশমার লেন্সের ফোকাস দূরত্ব নির্ণয় কর।', 'রহিম সাহেব ও তার পিতার চোখের ত্রুটি প্রতিকারের উপায় রশ্মিচিত্রসহ তুলনামূলক আলোচনা কর।', 1, 2, 3, 4, 'ঢা. বো.', 2023, 1);
INSERT OR IGNORE INTO cq_questions (id, subject_id, chapter_id, stem, part_ka, part_kha, part_ga, part_gha, marks_ka, marks_kha, marks_ga, marks_gha, board, year, is_active) VALUES (2, 52, 357, 'একটি আলোক রশ্মি পানি (প্রতিসরণাঙ্ক $1.33$) থেকে বায়ুতে আপতিত হচ্ছে। পানি-বায়ু বিভেদতলে সংকট কোণ $48.6^\circ$।', 'সংকট কোণ কাকে বলে?', 'আলোর প্রতিসরণের সময় কম্পাঙ্ক অপরিবর্তিত থাকে কেন?', 'আপতন কোণ $52^\circ$ হলে আলোক রশ্মির গতিপথ কীরূপ হবে? ব্যাখ্যা কর।', 'পূর্ণ অভ্যন্তরীণ প্রতিফলন কীভাবে অপটিক্যাল ফাইবার ও চিকিৎসাক্ষেত্রে ব্যবহৃত হয় তা বিশ্লেষণ কর।', 1, 2, 3, 4, 'রা. বো.', 2022, 1);
INSERT OR IGNORE INTO cq_questions (id, subject_id, chapter_id, stem, part_ka, part_kha, part_ga, part_gha, marks_ka, marks_kha, marks_ga, marks_gha, board, year, is_active) VALUES (3, 50, 331, '$A = x^2 - 5x + 1 = 0$ (যেখানে $x \neq 0$) একটি বীজগাণিতিক সমীকরণ।', 'উৎপাদকে বিশ্লেষণ কর: $p^2 - 9q^2$।', 'দেখাও যে, $x + \frac{1}{x} = 5$।', '$x^2 + \frac{1}{x^2}$ এবং $x^3 + \frac{1}{x^3}$ এর মান নির্ণয় কর।', 'প্রমাণ কর যে, $x^4 + \frac{1}{x^4} = 527$।', 1, 2, 3, 4, 'কু. বো.', 2023, 1);
